script:
frappe.ui.form.on('Expense Claim', {
    project(frm) {
        if (frm.doc.project && !frm.doc.expense_approver) {
            frappe.call({
                method: 'frappe.client.get',
                args: {
                    doctype: 'Project',
                    name: frm.doc.project
                },
                callback: function(r) {
                    if (r.message) {
                        const project = r.message;
                        const today = frappe.datetime.nowdate(); // Стандартный метод получения текущей даты
                        
                        // Ищем действующего руководителя проекта
                        const manager = project.custom_ts_details.find(item => {
                            if (item.pt_role === 'Руководитель проекта') {
                                const fromValid = !item.pt_valid_from || item.pt_valid_from <= today;
                                const toValid = !item.pt_valid_for || item.pt_valid_for >= today;
                                return fromValid && toValid;
                            }
                            return false;
                        });
                        
                        if (manager) {
                            frm.set_value('expense_approver', manager.pt_participant);
                            frappe.show_alert({
                                message: __('Действующий руководитель проекта назначен согласующим'),
                                indicator: 'green'
                            }, 3);
                        }
                    }
                }
            });
        }
    }
});
